// Rule L19: names in another case are written the way they were declared.

/// @sort 32
uniform float Strength = 2.0;

/// @name DreamShaderTests/Migrate/M_MgCase
export void M_MgCase(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    float2 MyUV = UE.TextureCoordinate(CoordinateIndex = 0);
    float Pulse = saturate(MyUV.x * Strength);
    Color = float3(Pulse, Pulse, Pulse);
    Base.EmissiveColor = Color;
}
